const body = $json.body ?? {};
const claims = $json.jwtPayload ?? {};
const expectedIssuer = $vars.SUPABASE_JWT_ISSUER;
if (!expectedIssuer) throw new Error('Missing n8n variable: SUPABASE_JWT_ISSUER');
if (!claims.sub) throw new Error('Verified Supabase JWT is missing sub');
if (claims.iss !== expectedIssuer || claims.role !== 'authenticated') throw new Error('JWT was not issued for this Supabase project');
if (body.user_id && body.user_id !== claims.sub) throw new Error('JWT user does not match request user');
if (!body.project_id) throw new Error('Missing required field: project_id');
const requestedCount = Math.min(90, Math.max(1, Number.parseInt(body.slide_count ?? '8', 10) || 8));
return [{ json: {
  mode: body.mode === 'assistant' ? 'assistant' : 'generate', project_id: body.project_id, session_id: body.session_id ?? '', user_id: claims.sub,
  message: body.message ?? '', description: body.description ?? '', purpose: body.purpose ?? 'Sales', slide_count: requestedCount,
  style: body.style ?? 'modern', font_set: body.font_set ?? 'grotesk', palette: body.palette ?? 'clay', ratio: body.ratio ?? '16:9',
  slides: Array.isArray(body.slides) ? body.slides : [], selected_slide_id: body.selected_slide_id ?? null, messages: Array.isArray(body.messages) ? body.messages.slice(-30) : [], asset_context: body.asset_context ?? ''
} }];

