parameters.jsCode:
const source = $input.first().json;
const raw = source.output ?? source.text ?? source;
let result = raw;
if (typeof raw === 'string') result = JSON.parse(raw.trim().replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim());
if (result?.output) result = result.output;
if (!Array.isArray(result?.slides)) throw new Error('Content Maker output is missing slides');
result.slides = result.slides.map((slide, index) => ({ ...slide, id: slide.id || ('slide-' + (index + 1)) }));
result.slideCount = result.slides.length;
result.generated_at = new Date().toISOString();
const input = $('Verify User and Normalize').first().json;
const messages = [...input.messages];
const last = messages[messages.length - 1];
if (input.message && !(last?.role === 'user' && last?.text === input.message)) messages.push({ id: 'user-' + Date.now(), role: 'user', text: input.message });
messages.push({ id: 'assistant-' + Date.now(), role: 'assistant', text: result.reply });
return [{ json: { ...input, title: result.slides[0]?.title || 'Untitled presentation', messages, result } }];
